        .version("0.8.0")
        .about("A typing practice tool using your own code repositories - extracts all code chunks (functions, classes, methods, etc.)")
        .long_about("GitType turns your own source code into typing challenges. Practice typing by using functions, classes, and methods from your actual projects. \n\nExamples:\n  gittype                           # Use current directory\n  gittype /path/to/repo             # Use specific repository\n  gittype --repo owner/repo         # Clone and use GitHub repository\n  gittype --langs rust,python       # Filter by languages")
        .arg(
            Arg::new("REPO_PATH")
                .help("Repository path to extract code from"),
        )
        .arg(
            Arg::new("repo")
                .long("repo")
                .value_name("REPO")
                .help("GitHub repository URL or path to clone and play with")
                .long_help("GitHub repository URL or path to clone and play with. Supports formats:\n  - owner/repo\n  - https://github.com/owner/repo\n  - git@github.com:owner/repo.git"),
        )
        .arg(
            Arg::new("langs")
