// Logging state
struct Logger {
    log_dir: Option<PathBuf>,
    log_file: Option<PathBuf>,
    file_ok: bool,
}

fn setup_logging() -> Logger {
    // Resolve home dir using dirs crate (which checks HOME env)
    let home = dirs::home_dir();
    let base: Option<PathBuf> = home.map(|h| h.join(".gittype").join("logs"));
    if base.is_none() {
        // Fallback? Should not happen, but treat as failure
        eprintln!("⚠️ Warning: Failed to setup file logging: IO error: No such file or directory (os error 2)");
        eprintln!("   Logs will only be shown in console.");
        return Logger { log_dir: None, log_file: None, file_ok: false };
    }
    let log_dir = base.unwrap();
    // Try to create dir
    if let Err(e) = std::fs::create_dir_all(&log_dir) {
        eprintln!("⚠️ Warning: Failed to setup file logging: IO error: {} (os error {})", error_message(&e), error_code(&e));
        eprintln!("   Logs will only be shown in console.");
        return Logger { log_dir: Some(log_dir), log_file: None, file_ok: false };
    }
    // File name based on local time
    let now = chrono::Local::now();
    let filename = format!("gittype_{}.log", now.format("%Y%m%d_%H%M%S"));
    let log_file = log_dir.join(&filename);
    // Try to open in append mode and write init line
    let timestamp = now.format("%Y-%m-%d %H:%M:%S").to_string();
    let init_line = format!("{} [INFO] gittype::infrastructure::logging - GitType logging initialized, logs saved to: {}\n", timestamp, log_dir.display());
    match std::fs::OpenOptions::new().create(true).append(true).open(&log_file) {
        Ok(mut f) => {
            if let Err(e) = f.write_all(init_line.as_bytes()) {
                eprintln!("⚠️ Warning: Failed to setup file logging: IO error: {} (os error {})", error_message(&e), error_code(&e));
                eprintln!("   Logs will only be shown in console.");
                return Logger { log_dir: Some(log_dir), log_file: Some(log_file), file_ok: false };
            }
            Logger { log_dir: Some(log_dir), log_file: Some(log_file), file_ok: true }
        }
        Err(e) => {
            eprintln!("⚠️ Warning: Failed to setup file logging: IO error: {} (os error {})", error_message(&e), error_code(&e));
            eprintln!("   Logs will only be shown in console.");
            Logger { log_dir: Some(log_dir), log_file: Some(log_file), file_ok: false }
        }
    }
}

fn error_message(e: &std::io::Error) -> String {
    // Extract message without "(os error N)" suffix? Actually Display includes it.
    // We need to get kind message: e.g., "Permission denied", "No such file or directory"
    // std::io::Error Display is "Permission denied (os error 13)" etc.
    // For our warning we need "Permission denied" part? Actually original warning is "IO error: Permission denied (os error 13)"
    // That's exactly e.to_string()? Let's check: e.to_string() for PermissionDenied is "Permission denied (os error 13)"
    // So "IO error: " + e.to_string()
    // But we need to extract code for separate? Actually e.to_string() already includes code, so we can just use it.
    // However our function returns full string, and caller adds code again? Let's just return kind string.
    // Simpler: match kind
    match e.kind() {
        std::io::ErrorKind::PermissionDenied => "Permission denied".to_string(),
        std::io::ErrorKind::NotFound => "No such file or directory".to_string(),
        _ => {
            // Try to get os error message?
            if let Some(code) = e.raw_os_error() {
                // Use generic?
                format!("{}", e)
            } else {
                format!("{}", e)
            }
        }
    }
}

fn error_code(e: &std::io::Error) -> i32 {
    e.raw_os_error().unwrap_or(0)
}

fn log_info(logger: &Logger, target: &str, msg: &str) {
    if !logger.file_ok {
        return;
    }
    if let Some(ref path) = logger.log_file {
        let now = chrono::Local::now();
        let ts = now.format("%Y-%m-%d %H:%M:%S").to_string();
        let line = format!("{} [INFO] {} - {}\n", ts, target, msg);
        if let Ok(mut f) = std::fs::OpenOptions::new().create(true).append(true).open(path) {
            let _ = f.write_all(line.as_bytes());
        }
    }
}

fn log_warn(logger: &Logger, target: &str, msg: &str) {
    if !logger.file_ok {
        return;
    }
    if let Some(ref path) = logger.log_file {
        let now = chrono::Local::now();
        let ts = now.format("%Y-%m-%d %H:%M:%S").to_string();
        let line = format!("{} [WARN] {} - {}\n", ts, target, msg);
        if let Ok(mut f) = std::fs::OpenOptions::new().create(true).append(true).open(path) {
            let _ = f.write_all(line.as_bytes());
        }
    }
}

fn log_error_block(logger: &Logger, error_message: &str, args: &[String]) {
    // Build error details block
    let now_utc = chrono::Utc::now();
    let ts_utc = now_utc.format("%Y-%m-%d %H:%M:%S").to_string();
    let exe = std::env::current_exe().map(|p| p.display().to_string()).unwrap_or_else(|_| args.get(0).cloned().unwrap_or_default());
    let cwd = std::env::current_dir().map(|p| p.display().to_string()).unwrap_or_default();
    // COMMAND_ARGS as JSON-like debug: ["./executable", "trending", "BadLang"]
    let cmd_args = {
        let mut s = String::from("[");
        for (i, a) in args.iter().enumerate() {
            if i > 0 { s.push_str(", "); }
            s.push_str(&format!("{:?}", a));
        }
        s.push(']');
        s
    };
    let os_str = std::env::consts::OS;
    let arch = std::env::consts::ARCH;
    let block = format!("ERROR OCCURRED AT: {} UTC\nERROR TYPE: \"gittype::domain::error::GitTypeError\"\nERROR MESSAGE: {}\nEXECUTABLE: {:?}\nWORKING_DIR: {:?}\nCOMMAND_ARGS: {}\nOS: {}\nARCH: {}\n\n",
        ts_utc, error_message, exe, cwd, cmd_args, os_str, arch);
    if logger.file_ok {
        if let Some(ref path) = logger.log_file {
            let now = chrono::Local::now();
            let ts = now.format("%Y-%m-%d %H:%M:%S").to_string();
            let header = format!("{} [ERROR] gittype::infrastructure::logging - APPLICATION ERROR:\n", ts);
            if let Ok(mut f) = std::fs::OpenOptions::new().create(true).append(true).open(path) {
                let _ = f.write_all(header.as_bytes());
                let _ = f.write_all(block.as_bytes());
            }
        }
    } else {
        // When file logging fails, print to stdout as original does: "[ERROR] APPLICATION ERROR:\n<block>"
        print!("[ERROR] APPLICATION ERROR:\n{}", block);
        let _ = std::io::stdout().flush();
    }
    // Write CWD error file
    let now2 = chrono::Local::now();
    let err_filename = format!("gittype_error_{}.log", now2.format("%Y%m%d_%H%M%S"));
    let _ = std::fs::write(&err_filename, block.as_bytes());
    // Return filename for stderr message
    // Caller will print to stderr
}

fn write_error_file_and_get_name(error_message: &str, args: &[String], logger: &Logger) -> String {
    let now_utc = chrono::Utc::now();
    let ts_utc = now_utc.format("%Y-%m-%d %H:%M:%S").to_string();
    let exe = std::env::current_exe().map(|p| p.display().to_string()).unwrap_or_else(|_| args.get(0).cloned().unwrap_or_default());
    let cwd = std::env::current_dir().map(|p| p.display().to_string()).unwrap_or_default();
    let cmd_args = {
        let mut s = String::from("[");
        for (i, a) in args.iter().enumerate() {
            if i > 0 { s.push_str(", "); }
            s.push_str(&format!("{:?}", a));
        }
        s.push(']');
        s
    };
    let os_str = std::env::consts::OS;
    let arch = std::env::consts::ARCH;
    let block = format!("ERROR OCCURRED AT: {} UTC\nERROR TYPE: \"gittype::domain::error::GitTypeError\"\nERROR MESSAGE: {}\nEXECUTABLE: {:?}\nWORKING_DIR: {:?}\nCOMMAND_ARGS: {}\nOS: {}\nARCH: {}\n\n",
        ts_utc, error_message, exe, cwd, cmd_args, os_str, arch);
    // Log to home log
    if logger.file_ok {
        if let Some(ref path) = logger.log_file {
            let now = chrono::Local::now();
            let ts = now.format("%Y-%m-%d %H:%M:%S").to_string();
            let header = format!("{} [ERROR] gittype::infrastructure::logging - APPLICATION ERROR:\n", ts);
            if let Ok(mut f) = std::fs::OpenOptions::new().create(true).append(true).open(path) {
                let _ = f.write_all(header.as_bytes());
                let _ = f.write_all(block.as_bytes());
            }
        }
    } else {
        print!("[ERROR] APPLICATION ERROR:\n{}", block);
        let _ = std::io::stdout().flush();
    }
    let now2 = chrono::Local::now();
    let err_filename = format!("gittype_error_{}.log", now2.format("%Y%m%d_%H%M%S"));
    let _ = std::fs::write(&err_filename, block.as_bytes());
    err_filename
}

