        }
        s.push(']');
        s
    };
    let os_str = std::env::consts::OS;
    let arch = std::env::consts::ARCH;
    let block = format!("ERROR OCCURRED AT: {} UTC\nERROR TYPE: \"gittype::domain::error::GitTypeError\"\nERROR MESSAGE: {}\nEXECUTABLE: {:?}\nWORKING_DIR: {:?}\nCOMMAND_ARGS: {}\nOS: {}\nARCH: {}\n\n",
        ts_utc, error_message, exe, cwd, cmd_args, os_str, arch);
    if logger.file_ok {
        if let Some(ref path) = logger.log_file {
            let now = chrono::Local::now();
            let ts = now.format("%Y-%m-%d %H:%M:%S").to_string();
            let header = format!("{} [ERROR] gittype::infrastructure::logging - APPLICATION ERROR:\n", ts);
            if let Ok(mut f) = std::fs::OpenOptions::new().create(true).append(true).open(path) {
                let _ = f.write_all(header.as_bytes());
                let _ = f.write_all(block.as_bytes());
            }
        }
    } else {
        // When file logging fails, print to stdout as original does: "[ERROR] APPLICATION ERROR:\n<block>"
