    // Write CWD error file
    let now2 = chrono::Local::now();
    let err_filename = format!("gittype_error_{}.log", now2.format("%Y%m%d_%H%M%S"));
    let _ = std::fs::write(&err_filename, block.as_bytes());
    // Return filename for stderr message
    // Caller will print to stderr
}

