    Ok(out)
}

fn parse_cache_key(data: &[u8]) -> Option<String> {
    if data.len() < 2 { return None; }
    // First byte is len of repo key
    let len1 = data[0] as usize;
    if data.len() < 1 + len1 + 1 { return None; }
    let repo = std::str::from_utf8(&data[1..1+len1]).ok()?;
    let pos = 1 + len1;
    let len2 = data[pos] as usize;
    if data.len() < pos + 1 + len2 { return None; }
    let commit = std::str::from_utf8(&data[pos+1..pos+1+len2]).ok()?;
    // Validate commit looks like hex 40? Not necessary, but check repo non-empty?
    if repo.is_empty() || commit.is_empty() { return None; }
    Some(format!("{}:{}", repo, commit))
}

