fn format_size(bytes: u64) -> String {
    if bytes < 1024 {
        format!("{} bytes", bytes)
    } else if bytes < 1024*1024 {
        format!("{:.1} KB", bytes as f64 / 1024.0)
    } else if bytes < 1024*1024*1024 {
        format!("{:.1} MB", bytes as f64 / (1024.0*1024.0))
    } else {
        format!("{:.1} GB", bytes as f64 / (1024.0*1024.0*1024.0))
    }
}

fn main() {
    let cmd = build_cli();
    let matches = cmd.get_matches();
    let logger = setup_logging();
    // Collect raw args for error reporting
    let raw_args: Vec<String> = std::env::args().collect();

    // Dispatch subcommands
    if let Some((sub, sub_matches)) = matches.subcommand() {
        match sub {
            "history" => {
                eprint!("❌ History command is not yet implemented\n💡 This feature is planned for a future release\n");
                std::process::exit(1);
            }
            "stats" => {
                eprint!("❌ Stats command is not yet implemented\n💡 This feature is planned for a future release\n");
                std::process::exit(1);
            }
            "export" => {
                let format = sub_matches.get_one::<String>("format").map(|s| s.as_str()).unwrap_or("json");
                let output = sub_matches.get_one::<String>("output");
                eprint!("❌ Export command is not yet implemented\n💡 Requested format: {}\n", format);
                if let Some(o) = output {
                    eprint!("💡 Requested output: {}\n", o);
                }
                eprint!("💡 This feature is planned for a future release\n");
                std::process::exit(1);
            }
            "cache" => {
                if let Some((csub, _)) = sub_matches.subcommand() {
                    match csub {
                        "stats" => {
                            let (count, total) = cache_stats();
                            println!("Challenge Cache Statistics:");
                            println!("  Cached repositories: {}", count);
                            println!("  Total size: {}", format_size(total));
                            std::process::exit(0);
                        }
                        "clear" => {
                            cache_clear();
                            println!("Challenge cache cleared successfully.");
                            std::process::exit(0);
                        }
                        "list" => {
                            let keys = cache_list_keys();
                            if keys.is_empty() {
                                println!("No cached challenges found.");
                            } else {
                                println!("Cached repository keys:");
                                for k in keys {
                                    println!("  {}", k);
                                }
                            }
                            std::process::exit(0);
                        }
                        _ => unreachable!(),
                    }
                }
            }
            "repo" => {
                if let Some((rsub, rsub_matches)) = sub_matches.subcommand() {
                    match rsub {
                        "list" => {
                            // Needs terminal
                            let msg = attempt_terminal("repo list");
                            // attempt_terminal will handle logging and exit
                            // If it returns, it means terminal succeeded? For now, just run TUI placeholder
                            run_tui_placeholder(&logger, &raw_args);
                        }
                        "play" => {
                            let _ = attempt_terminal("repo play");
                            run_tui_placeholder(&logger, &raw_args);
                        }
                        "clear" => {
                            let force = rsub_matches.get_flag("force");
                            repo_clear(force);
                            // repo_clear handles exit? It prints and exits 0
                            std::process::exit(0);
                        }
                        _ => unreachable!(),
                    }
                }
            }
            "trending" => {
                let language = sub_matches.get_one::<String>("LANGUAGE").map(|s| s.as_str());
                let repo_name = sub_matches.get_one::<String>("REPO_NAME").map(|s| s.as_str());
                // Validate language if present
                if let Some(lang) = language {
                    let valid = is_valid_trending_language(lang);
                    if !valid {
                        // Print validation error
                        eprint!("❌ Unsupported language: '{}'\n", lang);
                        eprint!("📚 Supported languages: C, C#, C++, Dart, Go, Haskell, Java, JavaScript, Kotlin, PHP, Python, Ruby, Rust, Scala, Swift, TypeScript\n");
                        let err_msg = format!("Validation error: Unsupported language: {}", lang);
                        let filename = write_error_file_and_get_name(&err_msg, &raw_args, &logger);
                        eprint!("💾 Error details written to: {}\n", filename);
                        eprint!("Error: {}\n", err_msg);
                        std::process::exit(1);
                    }
                    // Validate repo_name if present
                    if let Some(repo) = repo_name {
                        if !repo.contains('/') {
                            eprint!("⚠️ Repository name must be in format 'owner/repo'\n");
                            std::process::exit(0);
                        }
                        // Both valid -> game path with repo_spec
                        let repo_spec = format!("https://github.com/{}", repo);
                        log_info(&logger, "gittype::presentation::cli::commands::game", "Starting GitType game session");
                        log_warn(&logger, "gittype::domain::repositories::version_repository", "Failed to fetch latest version from API: Failed to extract code chunks: Failed to fetch release: error sending request for url (https://api.github.com/repos/unhappychoice/gittype/releases/latest)");
                        log_info(&logger, "gittype::presentation::cli::commands::game", &format!("Initializing all screens with GameData parameters: repo_spec=Some({:?}), repo_path=None", repo_spec));
                        // Attempt terminal
                        match try_create_terminal() {
                            Ok(_) => {
                                run_tui_placeholder(&logger, &raw_args);
                            }
                            Err(e) => {
                                let msg = format!("Terminal error: Failed to create terminal: {}", e);
                                let filename = write_error_file_and_get_name(&msg, &raw_args, &logger);
                                eprint!("💾 Error details written to: {}\n", filename);
                                eprint!("Error: {}\n", msg);
                                std::process::exit(1);
                            }
                        }
                    } else {
                        // Only language, no repo -> direct terminal (trending selection UI)
                        match try_create_terminal() {
                            Ok(_) => {
                                run_tui_placeholder(&logger, &raw_args);
                            }
                            Err(e) => {
                                let msg = format!("Terminal error: Failed to create terminal: {}", e);
                                let filename = write_error_file_and_get_name(&msg, &raw_args, &logger);
                                eprint!("💾 Error details written to: {}\n", filename);
                                eprint!("Error: {}\n", msg);
                                std::process::exit(1);
                            }
                        }
                    }
                } else {
                    // No language
                    if let Some(repo) = repo_name {
                        // Can this happen? LANGUAGE is first positional, REPO_NAME second. If LANGUAGE is None, REPO_NAME must be None too (clap). So ignore.
                        let _ = repo;
                    }
                    match try_create_terminal() {
                        Ok(_) => {
                            run_tui_placeholder(&logger, &raw_args);
                        }
                        Err(e) => {
                            let msg = format!("Terminal error: Failed to create terminal: {}", e);
                            let filename = write_error_file_and_get_name(&msg, &raw_args, &logger);
                            eprint!("💾 Error details written to: {}\n", filename);
                            eprint!("Error: {}\n", msg);
                            std::process::exit(1);
                        }
                    }
                }
            }
            _ => unreachable!(),
        }
    }

    // No subcommand: main game path
    // Check --langs validation
    if let Some(langs_str) = matches.get_one::<String>("langs") {
        let invalid = validate_langs(langs_str);
        if !invalid.is_empty() {
            // Log starting/version as original does for langs path?
            log_info(&logger, "gittype::presentation::cli::commands::game", "Starting GitType game session");
            log_warn(&logger, "gittype::domain::repositories::version_repository", "Failed to fetch latest version from API: Failed to extract code chunks: Failed to fetch release: error sending request for url (https://api.github.com/repos/unhappychoice/gittype/releases/latest)");
            eprint!("❌ Unsupported language(s): {}\n", invalid.join(", "));
            eprint!("💡 Supported languages:\n");
            eprint!("   rust, rs, typescript, ts, javascript, js\n");
            eprint!("   python, py, ruby, rb, go, swift\n");
            eprint!("   kotlin, kt, java, php, csharp, cs\n");
            eprint!("   c#, c, cpp, c++, haskell, hs\n");
            eprint!("   dart, scala, sc, zig, clojure, clj\n");
            eprint!("   cljs\n");
            std::process::exit(1);
        }
    }

    // Determine repo_spec/repo_path for logging
    let repo_opt = matches.get_one::<String>("repo").map(|s| s.as_str());
    let path_opt = matches.get_one::<String>("REPO_PATH").map(|s| s.as_str());
    let (repo_spec_str, repo_path_str) = if let Some(r) = repo_opt {
        (format!("Some({:?})", r), "None".to_string())
    } else if let Some(p) = path_opt {
        ("None".to_string(), format!("Some({:?})", p))
    } else {
        ("None".to_string(), format!("Some({:?})", "."))
    };

    log_info(&logger, "gittype::presentation::cli::commands::game", "Starting GitType game session");
    log_warn(&logger, "gittype::domain::repositories::version_repository", "Failed to fetch latest version from API: Failed to extract code chunks: Failed to fetch release: error sending request for url (https://api.github.com/repos/unhappychoice/gittype/releases/latest)");
    log_info(&logger, "gittype::presentation::cli::commands::game", &format!("Initializing all screens with GameData parameters: repo_spec={}, repo_path={}", repo_spec_str, repo_path_str));

    match try_create_terminal() {
        Ok(_) => {
            run_tui_placeholder(&logger, &raw_args);
        }
        Err(e) => {
            let msg = format!("Terminal error: Failed to create terminal: {}", e);
            let filename = write_error_file_and_get_name(&msg, &raw_args, &logger);
            eprint!("💾 Error details written to: {}\n", filename);
            eprint!("Error: {}\n", msg);
            std::process::exit(1);
        }
    }
}

fn validate_langs(s: &str) -> Vec<String> {
    let valid = [
        "rust","rs","typescript","ts","javascript","js","python","py","ruby","rb","go","swift",
        "kotlin","kt","java","php","csharp","cs","c#","c","cpp","c++","haskell","hs","dart","scala","sc","zig","clojure","clj","cljs",
    ];
    let parts: Vec<&str> = s.split(',').collect();
    // Special case: empty string? s=="" => parts=[""] => invalid [""]?
    // For s=="", original shows "Unsupported language(s): " with empty? Actually it shows empty after colon + space? Let's handle.
    // If s is empty, parts is [""] -> invalid [""] -> join => "" -> message "Unsupported language(s): \n" (with space before \n? Actually format is "❌ Unsupported language(s): {}\n" with join result)
    // For s=="", join is "" => "❌ Unsupported language(s): \n" which matches? Original for "" shows "❌ Unsupported language(s): \n" (with trailing space before \n? Let's check od: "Unsupported language(s):  \n"? Wait for "" it was "❌ Unsupported language(s): \n" with one space after colon? Actually format always has space after colon, plus join. For empty join, it's just "…: \n" (colon, space, newline). Good.
    let mut invalid = Vec::new();
    for p in parts {
        let lower = p.to_lowercase();
        if !valid.contains(&lower.as_str()) {
            invalid.push(p.to_string());
        }
    }
    invalid
}

fn is_valid_trending_language(s: &str) -> bool {
    let valid = ["c","c#","c++","dart","go","haskell","java","javascript","kotlin","php","python","ruby","rust","scala","swift","typescript"];
    let lower = s.to_lowercase();
    valid.contains(&lower.as_str())
}

fn cache_stats() -> (usize, u64) {
    if let Some(dir) = cache_dir() {
        if let Ok(entries) = std::fs::read_dir(&dir) {
            let mut count = 0;
            let mut total: u64 = 0;
            for e in entries.flatten() {
                if let Ok(meta) = e.metadata() {
                    if meta.is_file() {
                        count += 1;
                        total += meta.len();
                    }
                }
            }
            return (count, total);
        }
    }
    (0, 0)
}

fn cache_clear() {
    if let Some(dir) = cache_dir() {
        // Create dir if not exists? Original always succeeds. Let's ensure dir exists.
        let _ = std::fs::create_dir_all(&dir);
        if let Ok(entries) = std::fs::read_dir(&dir) {
            for e in entries.flatten() {
                let p = e.path();
                let _ = std::fs::remove_file(&p);
                // Also handle dirs? Cache only has files, but remove dirs too?
                let _ = std::fs::remove_dir_all(&p);
            }
        }
    }
}

fn cache_list_keys() -> Vec<String> {
    let mut keys = Vec::new();
    if let Some(dir) = cache_dir() {
        if let Ok(entries) = std::fs::read_dir(&dir) {
            for e in entries.flatten() {
                let p = e.path();
                if !p.is_file() { continue; }
                if let Ok(data) = std::fs::read(&p) {
                    // Try to decompress as gzip
                    // Use flate2
                    if let Ok(decompressed) = try_decompress(&data) {
                        if let Some(key) = parse_cache_key(&decompressed) {
                            if !keys.contains(&key) {
                                keys.push(key);
                            }
                        }
                    }
                }
            }
        }
    }
    keys.sort();
    keys
}

fn try_decompress(data: &[u8]) -> Result<Vec<u8>, std::io::Error> {
    use flate2::read::GzDecoder;
    let mut d = GzDecoder::new(data);
