    (["--help"], None), (["trending","--help"], None),
]
for args, stdin in cases:
    for f in glob.glob("/workspace/gittype_error_*.log"):
        try: os.remove(f)
        except: pass
    rc1,out1,err1=get("/workspace/executable",args)
    out1n,err1n=norm(out1),norm(err1)
    for f in glob.glob("/workspace/gittype_error_*.log"):
